-- 166K HRSA designations of health professional shortage areas -- where the US lacks doctors, dentists, and mental health care.
-- Auto-generated by scripts/gen_evidence_pages.py: 165,531 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("HPSA_DESIGNATION_DATE") as year, count(*) as records
from THE_LIBRARY.HEALTH.HEALTHCARE_SHORTAGE_AREAS
where "HPSA_DESIGNATION_DATE" is not null
group by 1
order by 1
